import heapq
class VideoSharingPlatform:
    def __init__(self):
        self.vid = {}
        self.likes = {}
        self.dislikes = {}
        self.views = {}
        self.free = []
        self.next = 0
    def upload(self, video):
        if self.free:
            i = heapq.heappop(self.free)
        else:
            i = self.next
            self.next += 1
        self.vid[i] = video
        self.likes[i] = self.dislikes[i] = self.views[i] = 0
        return i
    def remove(self, videoId):
        if videoId in self.vid:
            del self.vid[videoId]
            heapq.heappush(self.free, videoId)
    def watch(self, videoId, startMinute, endMinute):
        if videoId not in self.vid:
            return "-1"
        v = self.vid[videoId]
        self.views[videoId] += 1
        return v[startMinute:min(endMinute, len(v) - 1) + 1]
    def like(self, videoId):
        if videoId in self.vid:
            self.likes[videoId] += 1
    def dislike(self, videoId):
        if videoId in self.vid:
            self.dislikes[videoId] += 1
    def getLikesAndDislikes(self, videoId):
        if videoId not in self.vid:
            return [-1]
        return [self.likes[videoId], self.dislikes[videoId]]
    def getViews(self, videoId):
        return self.views.get(videoId, -1)

