class VideoSharingPlatform {
    unordered_map<int,string> vid;
    unordered_map<int,array<int,3>> stat;
    priority_queue<int, vector<int>, greater<int>> freeIds;
    int nxt = 0;
public:
    VideoSharingPlatform() {}
    int upload(string video) {
        int i;
        if (!freeIds.empty()) { i = freeIds.top(); freeIds.pop(); }
        else i = nxt++;
        vid[i] = video;
        stat[i] = {0,0,0};
        return i;
    }
    void remove(int videoId) {
        if (vid.count(videoId)) { vid.erase(videoId); freeIds.push(videoId); }
    }
    string watch(int videoId, int s, int e) {
        auto it = vid.find(videoId);
        if (it == vid.end()) return "-1";
        stat[videoId][2]++;
        int r = min(e, (int)it->second.size() - 1);
        return it->second.substr(s, r - s + 1);
    }
    void like(int videoId) { if (vid.count(videoId)) stat[videoId][0]++; }
    void dislike(int videoId) { if (vid.count(videoId)) stat[videoId][1]++; }
    vector<int> getLikesAndDislikes(int videoId) {
        if (!vid.count(videoId)) return {-1};
        return {stat[videoId][0], stat[videoId][1]};
    }
    int getViews(int videoId) { return vid.count(videoId) ? stat[videoId][2] : -1; }
};

