class VideoSharingPlatform {
    private Map<Integer,String> vid = new HashMap<>();
    private Map<Integer,int[]> stat = new HashMap<>();
    private PriorityQueue<Integer> freeIds = new PriorityQueue<>();
    private int nxt = 0;
    public VideoSharingPlatform() {}
    public int upload(String video) {
        int i = freeIds.isEmpty() ? nxt++ : freeIds.poll();
        vid.put(i, video);
        stat.put(i, new int[]{0,0,0});
        return i;
    }
    public void remove(int videoId) {
        if (vid.containsKey(videoId)) { vid.remove(videoId); freeIds.offer(videoId); }
    }
    public String watch(int videoId, int s, int e) {
        String v = vid.get(videoId);
        if (v == null) return "-1";
        stat.get(videoId)[2]++;
        int r = Math.min(e, v.length() - 1);
        return v.substring(s, r + 1);
    }
    public void like(int videoId) { if (vid.containsKey(videoId)) stat.get(videoId)[0]++; }
    public void dislike(int videoId) { if (vid.containsKey(videoId)) stat.get(videoId)[1]++; }
    public int[] getLikesAndDislikes(int videoId) {
        if (!vid.containsKey(videoId)) return new int[]{-1};
        int[] s = stat.get(videoId);
        return new int[]{s[0], s[1]};
    }
    public int getViews(int videoId) { return vid.containsKey(videoId) ? stat.get(videoId)[2] : -1; }
}

