class Heap {
    constructor(){this.a=[]}
    push(x){const a=this.a;a.push(x);let i=a.length-1;while(i>0){const p=(i-1)>>1;if(a[p]<=a[i])break;[a[p],a[i]]=[a[i],a[p]];i=p}}
    pop(){const a=this.a,t=a[0],l=a.pop();if(a.length){a[0]=l;let i=0;for(;;){let c=2*i+1;if(c>=a.length)break;if(c+1<a.length&&a[c+1]<a[c])c++;if(a[i]<=a[c])break;[a[i],a[c]]=[a[c],a[i]];i=c}}return t}
}
var VideoSharingPlatform = function() {
    this.vid = new Map(); this.stat = new Map(); this.free = new Heap(); this.nxt = 0;
};
VideoSharingPlatform.prototype.upload = function(video) {
    const i = this.free.a.length ? this.free.pop() : this.nxt++;
    this.vid.set(i, video); this.stat.set(i, [0,0,0]); return i;
};
VideoSharingPlatform.prototype.remove = function(id) {
    if (this.vid.has(id)) { this.vid.delete(id); this.free.push(id); }
};
VideoSharingPlatform.prototype.watch = function(id, s, e) {
    if (!this.vid.has(id)) return "-1";
    const v = this.vid.get(id); this.stat.get(id)[2]++;
    return v.slice(s, Math.min(e, v.length - 1) + 1);
};
